grid=[[1]*22 for _ in range(12)]
zeros={1:[1,2,3,5,7,8,9,12],2:[1],3:[1],4:[1,12],7:[1],8:[12],9:[1],10:[1,12],11:[1,2,5,6,7,8,9,11,12]}
for r,cs in zeros.items():
    for c in cs: grid[r][c]=0
# Fill all missing cells along rectangular border r=1..11, c=1..12
for c in range(1,13):
    if grid[1][c]==1: grid[1][c]=2
    if grid[11][c]==1: grid[11][c]=2
for r in range(1,12):
    if grid[r][1]==1: grid[r][1]=2
    if grid[r][12]==1: grid[r][12]=2
print('\n'.join(' '.join(map(str,row)) for row in grid))
